#!/usr/bin/env python3
"""List source commits by selected authors whose subject is absent in another repo.

Commits are considered cherry-picked if the first line of their commit message
(the git "subject") exists in the target repository history.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path


def git(repo: str, args: list[str]) -> str:
    try:
        return subprocess.check_output(
            ["git", "-C", repo, *args],
            text=True,
            stderr=subprocess.PIPE,
        )
    except subprocess.CalledProcessError as exc:
        print(exc.stderr, file=sys.stderr, end="")
        raise SystemExit(exc.returncode) from exc


def load_author_emails(path: Path) -> set[str]:
    emails: set[str] = set()
    pattern = re.compile(r"<([^>]+)>")
    for line in path.read_text(encoding="utf-8").splitlines():
        match = pattern.search(line)
        if match:
            emails.add(match.group(1).strip().lower())
        else:
            stripped = line.strip()
            if stripped and not stripped.startswith("#"):
                emails.add(stripped.lower())
    return emails


def parse_source_log(raw: str) -> list[tuple[str, str, str, str, str]]:
    commits: list[tuple[str, str, str, str, str]] = []
    for record in raw.split("\0"):
        if not record:
            continue
        fields = record.split("\t", 4)
        if len(fields) != 5:
            print(f"warning: skipped unparsable git log record: {record!r}", file=sys.stderr)
            continue
        commits.append(tuple(fields))  # type: ignore[arg-type]
    return commits


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "List non-merge commits from authors in a list whose subject is not "
            "present in a target repository."
        )
    )
    parser.add_argument("target_repo", help="repository to check for cherry-picked commits")
    parser.add_argument("--source-repo", default=".", help="source repository (default: current directory)")
    parser.add_argument("--authors-list", default="list.txt", help="file with 'Name <email>' entries")
    parser.add_argument("--since", default="2026-01-01 00:00:00", help="source commits lower date bound")
    parser.add_argument("--source-rev", default="HEAD", help="source revision/range to scan")
    parser.add_argument("--target-rev", default="HEAD", help="target revision/range to scan; use --all for all refs")
    parser.add_argument(
        "--format",
        choices=("tsv", "subjects"),
        default="tsv",
        help="output format: tsv includes hash/date/author/email/subject; subjects prints only subjects",
    )
    args = parser.parse_args()

    author_emails = load_author_emails(Path(args.authors_list))
    if not author_emails:
        print(f"no author emails found in {args.authors_list}", file=sys.stderr)
        return 2

    target_subjects = set(
        git(args.target_repo, ["log", args.target_rev, "--format=%s"]).splitlines()
    )

    source_raw = git(
        args.source_repo,
        [
            "log",
            args.source_rev,
            "--no-merges",
            f"--since={args.since}",
            "--date=short",
            "--format=%H%x09%ad%x09%ae%x09%an%x09%s%x00",
        ],
    )

    missing: list[tuple[str, str, str, str, str]] = []
    for commit_hash, date, email, author, subject in parse_source_log(source_raw):
        if email.lower() in author_emails and subject not in target_subjects:
            missing.append((commit_hash, date, email, author, subject))

    if args.format == "subjects":
        for _, _, _, _, subject in missing:
            print(subject)
    else:
        for commit_hash, date, email, author, subject in missing:
            print(f"{commit_hash}\t{date}\t{author} <{email}>\t{subject}")

    print(f"TOTAL\t{len(missing)}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

